#!/usr/bin/env python3
"""Turn two X11 PCF bitmap fonts into src/ui/font_data.c.

Usage: tools/genfont.py REGULAR.pcf.gz BOLD.pcf.gz > src/ui/font_data.c

Run by `make docs`. The output is committed so a build needs no fonts
installed. Only ASCII 32..126 is kept; the UI draws '?' for anything else.
"""
import gzip
import sys

from PIL import PcfFontFile

FIRST, LAST = 32, 126

NOTICE = """\
/*
 * Generated by tools/genfont.py from the X.Org font-adobe-75dpi package
 * (helvR12 and helvB12). Do not edit; run `make docs`.
 *
 * Copyright 1984-1989, 1994 Adobe Systems Incorporated.
 * Copyright 1988, 1994 Digital Equipment Corporation.
 *
 * Adobe is a trademark of Adobe Systems Incorporated which may be
 * registered in certain jurisdictions.
 * Permission to use these trademarks is hereby granted only in
 * association with the images described in this file.
 *
 * Permission to use, copy, modify, distribute and sell this software
 * and its documentation for any purpose and without fee is hereby
 * granted, provided that the above copyright notices appear in all
 * copies and that both those copyright notices and this permission
 * notice appear in supporting documentation, and that the names of
 * Adobe Systems and Digital Equipment Corporation not be used in
 * advertising or publicity pertaining to distribution of the software
 * without specific, written prior permission.  Adobe Systems and
 * Digital Equipment Corporation make no representations about the
 * suitability of this software for any purpose.  It is provided "as
 * is" without express or implied warranty.
 */
"""


def pack(image):
    """Return the glyph rows as bytes, each row padded to a whole byte."""
    width, height = image.size
    out = []
    for y in range(height):
        byte, used = 0, 0
        for x in range(width):
            byte = (byte << 1) | (1 if image.getpixel((x, y)) else 0)
            used += 1
            if used == 8:
                out.append(byte)
                byte, used = 0, 0
        if used:
            out.append(byte << (8 - used))
    return out


def emit(name, path):
    font = PcfFontFile.PcfFontFile(gzip.open(path))
    boxes = [font.glyph[code][1] for code in range(FIRST, LAST + 1)]
    ascent = max(-box[1] for box in boxes)
    descent = max(box[3] for box in boxes)
    bits, glyphs = [], []
    for code in range(FIRST, LAST + 1):
        (advance, _), (left, top, _, _), _, image = font.glyph[code]
        width, height = image.size
        glyphs.append((len(bits), width, height, left, -top, advance))
        bits.extend(pack(image))
    print(f"static const uint8_t {name}_bits[] = {{")
    for i in range(0, len(bits), 16):
        print("    " + ", ".join(f"0x{b:02x}" for b in bits[i:i + 16]) + ",")
    print("};\n")
    print(f"static const struct glyph {name}_glyphs[] = {{")
    for code, glyph in zip(range(FIRST, LAST + 1), glyphs):
        print("    {%d, %d, %d, %d, %d, %d}, /* %s */" % (*glyph, repr(chr(code))))
    print("};\n")
    print(f"const struct font font_{name} = {{{ascent}, {descent}, {name}_glyphs, {name}_bits}};\n")


def main():
    if len(sys.argv) != 3:
        sys.exit(__doc__)
    print(NOTICE)
    print('#include "ui/font.h"\n')
    emit("regular", sys.argv[1])
    emit("bold", sys.argv[2])


if __name__ == "__main__":
    main()
